from pathlib import Path
p=Path('components/WorkflowWorkspaceV2.tsx')
s=p.read_text()
old='''{selectedAvailability.length > 0 ? <section className="rounded-2xl border border-[#01A32E] bg-[#01A32E] p-4 shadow-sm">\n              <div className="flex items-center justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-wide text-white">I’m Available</p>{selectedAvailability.map((slot) => <div key={slot.id}><p className="mt-1 text-sm font-black text-white">{shortTime(slot.starts_at)}–{shortTime(slot.ends_at)}</p><p className="mt-0.5 text-xs font-extrabold text-white/90">${Number(slot.hourly_rate).toFixed(2)}/hr</p></div>)}</div><button type="button" disabled={busy === selectedAvailability[0].id} onClick={() => void run(selectedAvailability[0].id, () => removeProfessionalAvailability(selectedAvailability[0].id)).then((removed) => { if (removed) setAvailabilityOpen(true); })} className="secondary-btn">Change Rate / Hours</button></div>\n            </section>'''
new='''{selectedAvailability.length > 0 ? <section className="rounded-2xl border border-[#01A32E] bg-[#01A32E] p-4 shadow-sm">\n              <div className="flex items-start justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-wide text-white">I’m Available</p>{selectedAvailability.map((slot) => <div key={slot.id}><p className="mt-1 text-sm font-black text-white">{shortTime(slot.starts_at)}–{shortTime(slot.ends_at)}</p><form className="mt-2 flex items-center gap-2" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const rate = Number(form.get("day_rate") || 0); if (!Number.isFinite(rate) || rate <= 0) { setError("Enter a valid hourly rate."); return; } void run(`rate-${slot.id}`, async () => { await removeProfessionalAvailability(slot.id); await addProfessionalAvailability(userId, slot.starts_at, slot.ends_at, rate); }); }}><label className="flex items-center gap-1.5 text-xs font-black text-white"><span>$</span><input name="day_rate" type="number" min="1" step="0.50" defaultValue={Number(slot.hourly_rate).toFixed(2)} className="w-20 rounded-lg border border-white/50 bg-white px-2 py-1.5 text-right text-sm font-black text-[#002757] outline-none focus:ring-2 focus:ring-white/50" /><span>/hr</span></label><button type="submit" disabled={busy === `rate-${slot.id}`} className="rounded-lg bg-white px-2.5 py-1.5 text-xs font-black text-[#017f27] shadow-sm disabled:opacity-50">{busy === `rate-${slot.id}` ? "Saving…" : "Save"}</button></form></div>)}</div><button type="button" disabled={busy === selectedAvailability[0].id} onClick={() => void run(selectedAvailability[0].id, () => removeProfessionalAvailability(selectedAvailability[0].id)).then((removed) => { if (removed) setAvailabilityOpen(true); })} className="secondary-btn">Change Hours</button></div>\n            </section>'''
if old not in s: raise SystemExit('sidebar availability block anchor not found')
s=s.replace(old,new,1)
p.write_text(s)
print('Added direct inline hourly-rate editor to professional I’m Available sidebar card.')